import React from "react";
import jsPDF from "jspdf";
import "jspdf-autotable";
import Duty from "../duty/Duty";
import Trip from "../trip/Trip";
import DutyInfo from "../duty/DutyInfo";
import { Button, View } from "react-native";
import { OverTimeCalculationResult } from "../allowancecalculation/overtimeAllowance";

interface PDFGeneratorProps {
  duties: Duty[];
  designation: string;
  payBand: string;
  level: string;
  rateOfPay: number;
  selectedMonth: string;
  totalKilometers: number;
  mileage: number;
  nightDutyAllowance: number;
  nationalHolidayAllowance: number;
  leaveMileageAllowance: number;
  overTimeAllowance: number;
  dearnessAllowance: number;
  startDate: string;
  progressiveDutyHours: number;
  endDate: string;
  daysInMonth: number;
  overtimeResult: OverTimeCalculationResult | null;
}

const PDFGenerator: React.FC<PDFGeneratorProps> = ({
  duties,
  designation,
  payBand,
  level,
  rateOfPay,
  selectedMonth,
  totalKilometers,
  mileage,
  nightDutyAllowance,
  nationalHolidayAllowance,
  leaveMileageAllowance,
  overTimeAllowance,
  dearnessAllowance,
  startDate,
  progressiveDutyHours,
  endDate,
  daysInMonth,
  overtimeResult,
}) => {
  const generatePDF = () => {
    const doc = new jsPDF("l"); // Set landscape orientation
    const footerText = "This is generated by Allowance Calculator an Platform by Feyntech Optimization Solutions Pvt. Ltd.";
    let currentY = 20; // Start position for content
    let isHeaderRendered = false; // Flag to track if the header has been rendered on the current page

    // Header rendering function
    const renderHeader = () => {
      if (!isHeaderRendered || currentY + 40 > doc.internal.pageSize.getHeight() - 20) {
        if (!isHeaderRendered) {
          doc.autoTable({
            head: [headerData],
            theme: "grid",
            styles: { fontSize: 10, halign: "left" },
            margin: { top: 10, bottom: 10 },
          });
          currentY = doc.autoTableEndPosY() + 10; // Adjust the current position for header
          isHeaderRendered = true;
        } else {
          doc.addPage();
          doc.autoTable({
            head: [headerData],
            theme: "grid",
            styles: { fontSize: 10, halign: "left" },
            margin: { top: 10, bottom: 10 },
          });
          currentY = doc.autoTableEndPosY() + 10; // Adjust the current position for header on new page
        }
      }
    };

    // Add header row
    const headerData = [
      { content: "Designation", colSpan: 1, styles: { fontStyle: "bold", fillColor: [200, 230, 245], textColor: [0, 0, 0] }},
      { content: designation, colSpan: 1 },
      { content: "Pay Band", colSpan: 1, styles: { fontStyle: "bold" }},
      { content: payBand, colSpan: 1 },
      { content: "Level", colSpan: 1, styles: { fontStyle: "bold" }},
      { content: level, colSpan: 1 },
      { content: "Rate of Pay", colSpan: 1, styles: { fontStyle: "bold" }},
      { content: rateOfPay, colSpan: 1 },
      { content: "Selected Month", colSpan: 1, styles: { fontStyle: "bold" }},
      { content: selectedMonth, colSpan: 1 },
    ];

    renderHeader();

    duties.forEach((duty, dutyIndex) => {
      // Check if there's enough space for the duty data, if not, add a new page
      if (currentY + 50 > doc.internal.pageSize.getHeight() - 20) {
        doc.addPage();
        renderHeader();
        currentY = 20;
      }

      doc.setFontSize(9);
      doc.text(`Duty ${dutyIndex + 1}`, 14, currentY);
      currentY += 6;

      // Generate trip table and duty info for each duty
      const tripTable = [
        ["Date", "Type of Work", "Train No.", "Dep. Time", "Arr. Time", "Source", "Dest.", "Distance", "Duty Hours", "Allowance", "Remarks"],
        ...duty.trips.map(trip => [trip.date, trip.typeOfWork, trip.trainNumber, trip.departureTime, trip.arrivalTime, trip.sourceStation, trip.destinationStation, trip.distance.toString(), trip.dutyHours, trip.allowance.toString(), trip.remarks]),
      ];

      doc.autoTable({
        head: [tripTable[0]],
        body: tripTable.slice(1),
        theme: "grid",
        styles: { fontSize: 8 },
        startY: currentY,
      });

      currentY = doc.autoTableEndPosY() + 10;

      // Duty Info
      const dutyInfoData = [
        ["Sign In", duty.signIn ? duty.signIn.toLocaleString() : "-", "Sign Off", duty.signOff ? duty.signOff.toLocaleString() : "-", "Total Allowance:", `₹ ${duty.calculateTotalAllowance().toFixed(2)}`, "Total Distance:", `${duty.calculateTotalDistance().toFixed(2)} km`, "Duty Hours", `${duty.dutyHours.toFixed(2)} H`, "Night Duty Hours :", `${duty.nightDutyHours.toFixed(2)} H`],
        ["Progressive Duty Hours", `${duty.progressiveDutyHours.toFixed(2)} H`, "OSDA", duty.isOSDA ? "Yes" : "No", "RRA", duty.isRRA ? "Yes" : "No"],
      ];

      // Check space for Duty Info, if insufficient, add new page
      if (currentY + 40 > doc.internal.pageSize.getHeight() - 20) {
        doc.addPage();
        renderHeader();
        currentY = 20;
      }

      doc.autoTable({
        head: [],
        body: dutyInfoData,
        theme: "grid",
        styles: { fontSize: 8 },
        startY: currentY,
      });

      currentY = doc.autoTableEndPosY() + 10; // Update current position after Duty Info
    });

    // Summary block and Overtime results on a new page
    doc.addPage();
    renderHeader();

    const summaryBlockData = [
      [{ content: "Total Kilometers:", colSpan: 1, styles: { fontStyle: "bold" }}, { content: totalKilometers ? `${totalKilometers.toFixed(2)}` : "-", colSpan: 1 }],
      [{ content: "Mileage:", colSpan: 1, styles: { fontStyle: "bold" }}, { content: mileage ? `₹ ${mileage.toFixed(2)}` : "-", colSpan: 1 }],
      [{ content: "Night Duty Allowance:", colSpan: 1, styles: { fontStyle: "bold" }}, { content: nightDutyAllowance ? `₹ ${nightDutyAllowance.toFixed(2)}` : "-", colSpan: 1 }],
      [{ content: "Leave Mileage Allowance:", colSpan: 1, styles: { fontStyle: "bold" }}, { content: leaveMileageAllowance ? `₹ ${leaveMileageAllowance.toFixed(2)}` : "-", colSpan: 1 }],
      [{ content: "Dearness Allowance:", colSpan: 1, styles: { fontStyle: "bold" }}, { content: dearnessAllowance ? `₹ ${dearnessAllowance.toFixed(2)}` : "-", colSpan: 1 }],
      [{ content: "Progressive Duty Hours:", colSpan: 1, styles: { fontStyle: "bold" }}, { content: progressiveDutyHours ? `${progressiveDutyHours.toFixed(2)} H` : "-", colSpan: 1 }],
    ];

    doc.autoTable({
      head: [[{ content: "Summary Block", colSpan: 2, styles: { fontStyle: "bold", fillColor: [200, 230, 245], textColor: [0, 0, 0] }}]],
      body: summaryBlockData,
      theme: "grid",
      styles: { fontSize: 8 },
      margin: { top: 20 },
    });

    if (overtimeResult) {
      const overtimeResultData = [
        [{ content: "Fortnight", colSpan: 1, styles: { fontStyle: "bold" }},
         { content: "Start Date", colSpan: 1, styles: { fontStyle: "bold" }},
         { content: "End Date", colSpan: 1, styles: { fontStyle: "bold" }},
         { content: "Overtime Hours", colSpan: 1, styles: { fontStyle: "bold" }},
         { content: "Overtime Minutes", colSpan: 1, styles: { fontStyle: "bold" }},
         { content: "Overtime Unit", colSpan: 1, styles: { fontStyle: "bold" }}],
        [
          { content: "First Fortnight", colSpan: 1 },
          { content: overtimeResult.firstFortnight?.startDate.toDateString() || "-", colSpan: 1 },
          { content: overtimeResult.firstFortnight?.endDate.toDateString() || "-", colSpan: 1 },
          { content: overtimeResult.firstFortnight?.overtimeHours.toString() || "-", colSpan: 1 },
          { content: overtimeResult.firstFortnight?.overtimeMinutes.toString() || "-", colSpan: 1 },
          { content: overtimeResult.firstFortnight?.overtimeUnit.toString() || "-", colSpan: 1 }
        ],
        [
          { content: "Second Fortnight", colSpan: 1 },
          { content: overtimeResult.secondFortnight?.startDate.toDateString() || "-", colSpan: 1 },
          { content: overtimeResult.secondFortnight?.endDate.toDateString() || "-", colSpan: 1 },
          { content: overtimeResult.secondFortnight?.overtimeHours.toString() || "-", colSpan: 1 },
          { content: overtimeResult.secondFortnight?.overtimeMinutes.toString() || "-", colSpan: 1 },
          { content: overtimeResult.secondFortnight?.overtimeUnit.toString() || "-", colSpan: 1 }
        ]
      ];

      doc.autoTable({
        head: [
          [
            {
              content: "Overtime Calculation Result",
              colSpan: 6,
              styles: {
                fontStyle: "bold",
                fillColor: [200, 230, 245], // RGB array for the background color
                textColor: [0, 0, 0] // RGB array for the text color
              }
            }
          ]
        ],
        body: overtimeResultData,
        theme: "grid",
        styles: { fontSize: 8 },
        margin: { top: 20 },
      });

    doc.save("duty-report.pdf");
  };
  }
  return (
    <View>
      <Button title="Generate PDF" onPress={generatePDF} />
    </View>
  );
};

export default PDFGenerator;
